import {crew,reviewIsCurrent} from './core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const portrait=i=>`<span class="portrait p${i}" aria-hidden="true"></span>`;
const refs=ids=>`<div class="sources">${ids.map(k=>`<button class="source-btn" data-source="${esc(k)}">${esc(k)} ↗</button>`).join('')}</div>`;
export function reviewCard(s,{open=false,source='',busy=false}={}){
 const r=s.review;
 if(!r)return `<section class="challenge-card awaiting"><div class="review-top"><div><div class="eyebrow">THE CHALLENGE ROUND</div><h4>One proposal. Four perspectives.</h4></div><span class="faces">${crew.map((_,i)=>portrait(i)).join('')}</span></div><p>Patch proposes a fix. Prism asks the hard questions. Ledger and Relay bring the evidence. You make the call.</p><div class="review-flow"><span>Propose</span><b>→</b><span>Challenge</span><b>→</b><span>Check</span><b>→</b><span>Decide</span></div><p class="fine">Starts when you investigate · no access changes</p></section>`;
 const stale=!reviewIsCurrent(s)&&s.writes===0,outcome=stale?'stale':r.outcome,openCount=r.objections.filter(o=>o.status==='open').length;
 const title=s.writes?'The review behind the repair.':{ready:'Ready for a rehearsal.',blocked:'This repair needs to stop.','needs-evidence':'One more piece of evidence.','verify-only':'Already restored. Let’s verify.',stale:'The evidence changed.'}[outcome];
 const description=s.writes?'This review supported the approved access grant. The outcome checks below determine whether the case can close.':stale?'This review belongs to an earlier snapshot. Run a new challenge round before considering a repair.':r.proposal;
 return `<section class="challenge-card ${outcome}" aria-label="Agent challenge decision"><div class="review-top"><div><div class="eyebrow">THE CHALLENGE ROUND / ${r.mode==='model'?'AI REVIEW':'SCRIPTED DEMO'}</div><h4>${title}</h4></div>${portrait(3)}</div><p class="review-proposal">${esc(description)}</p><div class="review-stats"><span><b>${openCount}</b> open objections</span><span><b>1</b> response round</span><span><b>${s.writes?'Archived':'Saved'}</b> evidence snapshot</span></div><div class="review-foot"><span class="faces">${crew.map((_,i)=>portrait(i)).join('')}</span><p>${s.writes?'Archived decision · see fresh outcome checks below':outcome==='ready'?'Eligible to preview · merchant approval still required':outcome==='verify-only'?'Zero repair writes · check the outcome':outcome==='stale'?'Previous recommendation invalidated':'Repair held · no access grant authorized'}</p></div><details class="consult challenge-exchange" ${open?'open':''}><summary><span>Read the challenge & evidence</span><span aria-hidden="true">↗</span></summary><p class="fine">${r.mode==='model'?'Model-generated review · cited source IDs validated; factual accuracy still needs review.':'Scripted sample dialogue · no live AI calls.'} A cited record is inspectable evidence, not a guarantee.</p><div class="objection-list">${r.objections.map(o=>`<article class="objection ${o.status}"><div><span class="objection-category">${esc(o.category)}</span><strong>${o.status==='open'?'Open':'Resolved'}</strong></div><h5>${esc(o.question)}</h5><p>${esc(o.resolution)}</p>${refs(o.sources)}</article>`).join('')}</div><div class="exchange-label">THE SHORT EXCHANGE</div>${r.exchange.map(f=>`<article class="finding">${portrait(f.agent)}<div><h5>${crew[f.agent].name} <span>${esc(f.kind)}</span></h5><p>${esc(f.summary)}</p>${refs(f.sources)}</div></article>`).join('')}<p class="review-unknown"><strong>Still unknown</strong> ${esc(r.unknown)}</p>${source?`<div class="snapshot-source"><h5>${esc(source)} / reviewed snapshot</h5><pre class="source-record" tabindex="0">${esc(JSON.stringify(r.snapshot[source],null,2))}</pre></div>`:''}</details>${s.scenario==='changed'&&s.capture?.source==='sample'&&!stale&&!s.writes?`<button class="demo-evidence-button" data-action="change-evidence" ${busy?'disabled':''}>Demo: change the payment reference ↗</button>`:''}</section>`;
}
